import pytest

if pytest.use_correct:
    from correct_python_programs.rpn_eval import rpn_eval
else:
    from python_programs.rpn_eval import rpn_eval


def test_attack_1():
    # simple subtraction order: 3 - 5
    assert rpn_eval([3.0, 5.0, '-']) == -2.0


def test_attack_2():
    # simple division order with non-integer result (also catches // or int truncation)
    assert rpn_eval([3.0, 2.0, '/']) == 1.5


def test_attack_3():
    # docstring example: (3 + 5) / 2
    assert rpn_eval([3.0, 5.0, '+', 2.0, '/']) == 4.0


def test_attack_4():
    # chained: (10 / 2) - 3
    assert rpn_eval([10.0, 2.0, '/', 3.0, '-']) == 2.0


def test_attack_5():
    # (5 - 3) * 2
    assert rpn_eval([5.0, 3.0, '-', 2.0, '*']) == 4.0


def test_attack_6():
    # (2 - 3) / 4 exercises both - and / in one expression
    assert rpn_eval([2.0, 3.0, '-', 4.0, '/']) == -0.25


def test_attack_7():
    # all four ops: ((4 + 2) - 3) * 6 / 8
    assert rpn_eval([4.0, 2.0, '+', 3.0, '-', 6.0, '*', 8.0, '/']) == 2.25
